import{_ as a,o as t,c as r,a5 as o}from"./chunks/framework.DOB-AMqW.js";const u=JSON.parse('{"title":"Card Nest Support","description":"Standalone support information for Card Nest.","frontmatter":{"title":"Card Nest Support","description":"Standalone support information for Card Nest.","navbar":false,"sidebar":false,"aside":false,"outline":false,"footer":false,"prev":false,"next":false,"editLink":false,"lastUpdated":false,"pageClass":"standalone-policy"},"headers":[],"relativePath":"support/card-nest.md","filePath":"support/card-nest.md"}'),s={name:"support/card-nest.md"};function n(i,e,l,d,p,c){return t(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="card-nest-support" tabindex="-1">Card Nest Support <a class="header-anchor" href="#card-nest-support" aria-label="Permalink to &quot;Card Nest Support&quot;">​</a></h1><p>For Card Nest support, email <strong><a href="mailto:anand.official.in@gmail.com" target="_blank" rel="noreferrer">anand.official.in@gmail.com</a></strong>.</p><p>Include the Card Nest version, Android version, device model, a description of the issue, and safe reproduction steps when possible.</p><p>Never email full card numbers, CVVs, application PINs, receipt images, unredacted financial records, <code>.cnbak</code> files, or exported reports.</p><h2 id="common-help" tabindex="-1">Common help <a class="header-anchor" href="#common-help" aria-label="Permalink to &quot;Common help&quot;">​</a></h2><ul><li><strong>Forgotten application PIN:</strong> Card Nest does not store a recoverable PIN. Clearing Android app storage or reinstalling also removes local data; preserve a usable encrypted backup before doing so.</li><li><strong>Biometric unlock unavailable:</strong> unlock with the application PIN and confirm that Android has an enrolled supported biometric.</li><li><strong>Backup restore fails:</strong> select a Card Nest <code>.cnbak</code> file and enter the exact backup passphrase used when it was created.</li><li><strong>Reminder missing:</strong> enable Card Nest notifications and review Android battery and notification settings. Always verify due dates with the issuer.</li><li><strong>Receipt capture fails:</strong> grant camera permission for new photos or use the system photo picker for an existing image.</li><li><strong>Report export fails:</strong> choose an available writable destination and retry.</li></ul>',6)])])}const m=a(s,[["render",n]]);export{u as __pageData,m as default};
